// Check the intake sheet rows for XT Trip Discount Codes (#355). Reads only the outputs of earlier
// nodes; makes no HTTP call, reads no environment value and never sees a secret except to check that
// the Shopify sign-in step worked. Owner rules (24 Nov 2026): never create a Shopify customer; a code
// is made only for an existing customer whose email matches exactly; row problems stay in the sheet.
// 1. Refuse the whole run (nothing written anywhere, one error alert) when the settings (or the
//    sheet layout in SHEET_LAYOUT) are not valid, the sheet could not be read, a header the layout
//    names is missing or appears twice in row 1, or the Shopify sign-in failed.
// 2. Skip rows that are not ticked Ready, and rows whose Status is already DONE, ADOPTED or
//    EXPIRED_NO_ACCOUNT.
// 3. Check each remaining row: CHECK_ROW names every bad field (booking no. format, dates, email
//    format, a second row with the same code, and the traveller no. when the layout has one);
//    NEEDS_EMAIL when the email is empty; CHECK_EMAIL when another row on the same trip already has
//    the same email. A status the workflow did not write (the consultant's old Active, Expired) counts
//    as not processed yet; a code already in the code column is only a hint (Shopify is asked).
// 4. For each good row, work out the code (XT-INV<digits>, or XT-INV<digits>-<NN> plus the old name
//    for traveller 1 when the layout has a traveller column) and the end date (VALIDITY_RULE later =
//    max(deposit + 12 months, departure), earlier = min; 23:59:59 SGT), and queue one Shopify lookup.
// 5. Brake: more than 300 lookups waiting -> no lookup at all, those rows HELD, one error alert.
// 6. DRY_RUN: nothing is written; the plan is this node's (or Decide Code Writes') output.
// ---- the sheet layout: the only place columns come from is Run Settings SHEET_LAYOUT ---- //
// Roles map to header names (row 1). Columns are found by header at run time, so this node holds no
// column name or letter. A required role must name a header that appears exactly once in row 1; an
// optional role may be '' or null (not read or written).
// Without a traveller role there is one code per booking-no. row, named XT-INV<digits> (layout v2, F1 (a));
// with one, codes are XT-INV<digits>-<NN> and traveller 1 also matches the old name XT-INV<digits>.
const REQUIRED_ROLES = ['ready', 'invoice', 'email', 'deposit', 'departure', 'code', 'status', 'message'];
const OPTIONAL_ROLES = ['traveller', 'trip', 'ends', 'customer', 'checked', 'made'];
const layoutOf = (raw) => {
  if (!raw || typeof raw !== 'object' || typeof raw.tab !== 'string' || !/^[^'!]{1,100}$/.test(raw.tab)) return null;
  if (!Number.isInteger(raw.last_row) || raw.last_row < 2 || raw.last_row > 5000) return null;
  let invoiceRe;
  try { invoiceRe = new RegExp(String(raw.invoice_pattern)); } catch (e) { return null; }
  if (!/\((?!\?)/.test(String(raw.invoice_pattern))) return null; // must capture the invoice digits
  const cols = raw.columns;
  if (!cols || typeof cols !== 'object') return null;
  const names = {};
  for (const role of REQUIRED_ROLES.concat(OPTIONAL_ROLES)) {
    const name = cols[role] === null || cols[role] === undefined ? '' : cols[role];
    if (typeof name !== 'string' || name.length > 100) return null;
    if (!name.trim() && REQUIRED_ROLES.includes(role)) return null;
    names[role] = name.trim();
  }
  if (Object.keys(cols).some((role) => !(role in names))) return null;
  const used = Object.values(names).filter((n) => n);
  if (new Set(used).size !== used.length) return null; // two roles on one column
  return { tab: raw.tab, lastRow: raw.last_row, invoiceRe, names };
};
const locate = (layout, header) => {
  const cells = (header || []).map((h) => (h === undefined || h === null ? '' : String(h)).trim());
  const at = {};
  for (const [role, name] of Object.entries(layout.names)) {
    if (!name) { at[role] = -1; continue; }
    const hits = cells.reduce((list, h, i) => (h === name ? list.concat(i) : list), []);
    if (hits.length !== 1) return null;
    at[role] = hits[0];
  }
  return at;
};
const FINAL = ['DONE', 'ADOPTED', 'EXPIRED_NO_ACCOUNT'];
const LOOKUP_CAP = 300;
const EMAIL_RE = /^[^\s@"\\]{1,64}@[^\s@"\\]{1,190}\.[^\s@"\\]{2,63}$/;
const SGT_MS = 8 * 3600 * 1000; // Singapore has no daylight saving time.
const DAY_MS = 24 * 3600 * 1000;
const SERIAL_EPOCH = Date.UTC(1899, 11, 30); // Google Sheets date serial 0
const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
// One read per row: the customer with exactly this email (customerByIdentifier, the same exact lookup
// the member sync uses) and the code under its new name and, for traveller 1, its old name.
const LOOKUP_QUERY = 'query XtCodeLookup($email: String!, $code: String!, $legacy: String!, $withLegacy: Boolean!, '
  + '$withCustomer: Boolean!) { customer: customerByIdentifier(identifier: {emailAddress: $email}) '
  + '@include(if: $withCustomer) { id defaultEmailAddress { emailAddress } } '
  + 'code: codeDiscountNodeByCode(code: $code) { ...XtCode } '
  + 'legacy: codeDiscountNodeByCode(code: $legacy) @include(if: $withLegacy) { ...XtCode } } '
  + 'fragment XtCode on DiscountCodeNode { id codeDiscount { __typename ... on DiscountCodeBasic { status usageLimit '
  + 'asyncUsageCount endsAt combinesWith { orderDiscounts productDiscounts shippingDiscounts } '
  + 'customerGets { value { __typename ... on DiscountPercentage { percentage } } } '
  + 'context { __typename ... on DiscountCustomers { customers { id } } } } } }';

const now = Date.now();
const stamp = (ms) => {
  const d = new Date(ms + SGT_MS);
  return d.getUTCDate() + ' ' + MONTHS[d.getUTCMonth()] + ' ' + d.getUTCFullYear() + ' '
    + String(d.getUTCHours()).padStart(2, '0') + ':' + String(d.getUTCMinutes()).padStart(2, '0');
};
const checked = stamp(now);
const mask = (email) => {
  const [user, domain] = String(email).split('@');
  return (user || '').slice(0, 1) + '***@' + String(domain || '').slice(0, 1) + '***';
};
const failed = (code) => [{ json: { mode: 'failed', dry_run: true, updates: [], lookups: [], plan: [], problems: [{ code, count: 1 }] } }];

// ---- 1. settings, sheet and sign-in ---- //
const settings = $('Run Settings').first().json;
const dryRun = settings.DRY_RUN !== false;
if (settings.VALIDITY_RULE !== 'later' && settings.VALIDITY_RULE !== 'earlier') return failed('settings_invalid');
const layout = layoutOf(settings.SHEET_LAYOUT);
if (!layout) return failed('settings_invalid');
const sheet = $('Read Intake Sheet').first().json || {};
if (sheet.error !== undefined || !Array.isArray(sheet.values) || !sheet.values.every(Array.isArray)) return failed('sheet_read_failed');
const COL = locate(layout, sheet.values[0]);
if (!COL) return failed('sheet_layout_changed');
if (sheet.values.length > layout.lastRow) return failed('sheet_layout_changed');
const label = layout.names; // the sheet's own header names, for CHECK_ROW messages
const token = $('Get Shopify Access Token').first().json || {};
if (token.error !== undefined || typeof token.access_token !== 'string' || token.access_token.length < 10) return failed('token_failed');

// ---- 2. and 3. the rows ---- //
const toDate = (value) => {
  if (typeof value !== 'number' || !Number.isFinite(value)) return null;
  const days = Math.floor(value);
  if (days < 40000 || days > 80000) return null; // 2009 .. 2119
  const d = new Date(SERIAL_EPOCH + days * DAY_MS);
  return { y: d.getUTCFullYear(), m: d.getUTCMonth() + 1, d: d.getUTCDate() };
};
const num = (x) => x.y * 10000 + x.m * 100 + x.d;
const plusYear = (x) => ({ y: x.y + 1, m: x.m, d: x.m === 2 && x.d === 29 ? 28 : x.d });
const travellerOf = (value) => {
  const text = typeof value === 'number' ? String(value) : String(value === undefined || value === null ? '' : value).trim();
  return /^[0-9]{1,2}$/.test(text) && Number(text) >= 1 && Number(text) <= 99 ? Number(text) : null;
};
const text = (value) => (value === undefined || value === null ? '' : String(value)).trim();

const rows = sheet.values.slice(1).map((cells, i) => {
  const c = cells;
  const invoice = layout.invoiceRe.exec(text(c[COL.invoice]));
  const traveller = COL.traveller >= 0 ? travellerOf(c[COL.traveller]) : null;
  const code = !invoice ? '' : (COL.traveller < 0 ? 'XT-INV' + invoice[1]
    : (traveller ? 'XT-INV' + invoice[1] + '-' + String(traveller).padStart(2, '0') : ''));
  const email = text(c[COL.email]).toLowerCase();
  return { row: i + 2, c, invoice, traveller, code, email, status: text(c[COL.status]).toUpperCase(),
    trip: (COL.trip >= 0 ? text(c[COL.trip]) : '') || (invoice ? invoice[0] : ''), ready: c[COL.ready] === true };
});
const todo = rows.filter((r) => r.ready && !FINAL.includes(r.status));

const decided = [];
const lookups = [];
const update = (r, status, message) => decided.push({ row: r.row, status, message, code: '', ends: '', customer: '',
  checked, made: '', key: { invoice: text(r.c[COL.invoice]), traveller: COL.traveller >= 0 ? text(r.c[COL.traveller]) : '', email: r.email } });
for (const r of todo) {
  const bad = [];
  if (!r.invoice) bad.push(label.invoice);
  if (COL.traveller >= 0 && !r.traveller) bad.push(label.traveller);
  const deposit = toDate(r.c[COL.deposit]);
  const departure = toDate(r.c[COL.departure]);
  if (!deposit) bad.push(label.deposit);
  if (!departure) bad.push(label.departure);
  else if (deposit && num(departure) < num(deposit)) bad.push(label.departure + ' (before ' + label.deposit + ')');
  if (r.email && !EMAIL_RE.test(r.email)) bad.push(label.email);
  const twin = r.code ? rows.find((o) => o.row !== r.row && o.code === r.code) : null;
  if (twin) bad.push((COL.traveller >= 0 ? label.invoice + ' and ' + label.traveller : label.invoice)
    + ' (same as row ' + twin.row + ')');
  if (bad.length) { update(r, 'CHECK_ROW', 'Check: ' + bad.join(', ') + '.'); continue; }
  if (!r.email) { update(r, 'NEEDS_EMAIL', "Add this traveller's own email."); continue; }
  const sameEmail = rows.find((o) => o.row !== r.row && o.email === r.email && o.trip === r.trip && o.code !== r.code
    && (FINAL.includes(o.status) || (o.ready && o.row < r.row)));
  if (sameEmail) {
    update(r, 'CHECK_EMAIL', 'Same email as row ' + sameEmail.row + ' on the same trip. Each traveller needs their own email.');
    continue;
  }
  const yearOn = plusYear(deposit);
  const later = num(yearOn) >= num(departure) ? yearOn : departure;
  const earlier = num(yearOn) <= num(departure) ? yearOn : departure;
  const end = settings.VALIDITY_RULE === 'later' ? later : earlier;
  const endMs = Date.UTC(end.y, end.m - 1, end.d, 15, 59, 59); // 23:59:59 SGT
  const legacy = r.traveller === 1 ? r.code.replace(/-01$/, '') : '';
  lookups.push({ row: r.row, code: r.code, legacy, email: r.email, email_masked: mask(r.email),
    end_iso: new Date(endMs).toISOString(), end_serial: Math.round((Date.UTC(end.y, end.m - 1, end.d) - SERIAL_EPOCH) / DAY_MS),
    end_label: end.d + ' ' + MONTHS[end.m - 1] + ' ' + end.y + ' 23:59',
    expired: endMs < now, checked, key: { invoice: text(r.c[COL.invoice]), traveller: COL.traveller >= 0 ? text(r.c[COL.traveller]) : '', email: r.email },
    query: LOOKUP_QUERY,
    variables: { email: r.email, code: r.code, legacy: legacy || r.code, withLegacy: legacy !== '', withCustomer: endMs >= now } });
}

// ---- 5. lookup brake ---- //
const problems = [];
let queued = lookups;
if (lookups.length > LOOKUP_CAP) {
  for (const l of lookups) {
    decided.push({ row: l.row, status: 'HELD', message: 'Too many rows at once; tried again next morning.', code: '',
      ends: '', customer: '', checked, made: '', key: l.key });
  }
  problems.push({ code: 'too_many_rows', count: lookups.length });
  queued = [];
}

// ---- 6. the result ---- //
const plan = decided.map((d) => ({ row: d.row, status: d.status, message: d.message }));
if (dryRun) {
  return [{ json: { mode: queued.length ? 'lookup' : 'dry_run', dry_run: true, decided, updates: [], lookups: queued,
    plan, problems: [], summary: { rows: rows.length, ready: todo.length, decided: decided.length, lookups: queued.length,
      held: queued.length === lookups.length ? 0 : lookups.length } } }];
}
return [{ json: { mode: queued.length ? 'lookup' : (decided.length ? 'sheet_only' : 'no_change'), dry_run: false, decided,
  updates: queued.length ? [] : decided, lookups: queued, plan: [], problems,
  summary: { rows: rows.length, ready: todo.length, decided: decided.length, lookups: queued.length } } }];

// Decide each looked-up row for XT Trip Discount Codes (#355). Reads only earlier outputs: the rows
// Check Intake Rows queued (List Lookups) and Shopify's answer to each (Look Up Shopify, same order).
// No customer is ever created, edited or tagged (owner O1, 24 Nov 2026).
// - Lookup failed (HTTP, GraphQL, throttled, no data): ERROR, retried next run.
// - End date already passed: no code -> EXPIRED_NO_ACCOUNT; a code exists -> CONFLICT.
// - No customer with exactly this email: NEEDS_SHOPIFY_ACCOUNT (checked again every run).
// - A code already exists under the new name (or, for traveller 1, the old name):
//   locked to exactly this one customer and passing the guard (at most 3 uses so far, 15% off) ->
//   ADOPT: one discountCodeBasicUpdate setting only usageLimit 3, endsAt and combinesWith (none), or no
//   write at all when it already has exactly those; anything else -> CONFLICT, nothing changes.
// - Otherwise CREATE: discountCodeBasicCreate, 15% off all items, this one customer, 3 uses,
//   combines with nothing, ends per the validity rule, tag X-Trekkers.
// Brake: more than 30 code writes (creates plus adopt updates) -> none at all, those rows HELD, one
// error alert. DRY_RUN: no writes, the plan is this node's output.
const WRITE_CAP = 30;
const SHARE = 0.15;
const USES = 3;
const NONE = { orderDiscounts: false, productDiscounts: false, shippingDiscounts: false };
const CREATE = 'mutation XtCodeCreate($basicCodeDiscount: DiscountCodeBasicInput!) { discountCodeBasicCreate('
  + 'basicCodeDiscount: $basicCodeDiscount) { codeDiscountNode { id codeDiscount { __typename ... on DiscountCodeBasic { '
  + 'usageLimit endsAt codes(first: 1) { nodes { code } } } } } userErrors { field code message } } }';
const ADOPT = 'mutation XtCodeAdopt($id: ID!, $basicCodeDiscount: DiscountCodeBasicInput!) { discountCodeBasicUpdate('
  + 'id: $id, basicCodeDiscount: $basicCodeDiscount) { codeDiscountNode { id codeDiscount { __typename ... on '
  + 'DiscountCodeBasic { usageLimit endsAt } } } userErrors { field code message } } }';
const CUSTOMER_RE = /^gid:\/\/shopify\/Customer\/([0-9]{1,20})$/;
const NODE_RE = /^gid:\/\/shopify\/DiscountCodeNode\/[0-9]{1,20}$/;

const base = $('Check Intake Rows').first().json;
const lookups = $('List Lookups').all().map((item) => item.json);
const results = $input.all().map((item) => item.json);
const dryRun = base.dry_run !== false;
const decided = [];
const writes = [];
const problems = (base.problems || []).slice();
const rowOf = (l, status, message, extra) => ({ row: l.row, status, message, code: '', ends: '', customer: '',
  checked: l.checked, made: '', key: l.key, ...(extra || {}) });

const failure = (result) => {
  if (!result || typeof result !== 'object') return 'no_result';
  if (result.error !== undefined) return 'request_failed';
  if (Array.isArray(result.errors) && result.errors.length) {
    return result.errors.some((e) => e && e.extensions && e.extensions.code === 'THROTTLED') ? 'throttled' : 'graphql_errors';
  }
  if (!result.data || typeof result.data !== 'object') return 'no_data';
  return '';
};
// What an existing code is: whose it is, and whether it passes the adopt guard.
const inspect = (node, customerId, l) => {
  const cd = node && node.codeDiscount;
  if (!cd || cd.__typename !== 'DiscountCodeBasic' || !NODE_RE.test(String(node.id))) return { conflict: 'is not a simple code' };
  const owners = cd.context && cd.context.__typename === 'DiscountCustomers' && Array.isArray(cd.context.customers)
    ? cd.context.customers.map((c) => c && c.id) : null;
  if (!owners || owners.length !== 1 || owners[0] !== customerId) return { conflict: 'belongs to a different customer' };
  if (!(Number.isInteger(cd.asyncUsageCount) && cd.asyncUsageCount <= USES)) return { conflict: 'has been used more than 3 times' };
  const value = cd.customerGets && cd.customerGets.value;
  if (!value || value.__typename !== 'DiscountPercentage' || Math.abs(Number(value.percentage) - SHARE) > 1e-9) {
    return { conflict: 'is not 15% off' };
  }
  const c = cd.combinesWith || {};
  const atDefaults = cd.usageLimit === USES && Date.parse(cd.endsAt) === Date.parse(l.end_iso)
    && c.orderDiscounts === false && c.productDiscounts === false && c.shippingDiscounts === false;
  return { atDefaults };
};

if (results.length !== lookups.length) {
  for (const l of lookups) decided.push(rowOf(l, 'ERROR', 'Shopify could not be checked; tried again next morning.'));
  problems.push({ code: 'lookup_failed', count: lookups.length });
} else {
  let lookupFailed = 0;
  lookups.forEach((l, i) => {
    const result = results[i];
    if (failure(result)) {
      lookupFailed += 1;
      decided.push(rowOf(l, 'ERROR', 'Shopify could not be checked; tried again next morning.'));
      return;
    }
    const data = result.data;
    const fresh = data.code || null;
    const old = l.legacy ? (data.legacy || null) : null;
    if (l.expired) {
      if (!fresh && !old) decided.push(rowOf(l, 'EXPIRED_NO_ACCOUNT', 'End date passed before a code could be made; no code made.'));
      else decided.push(rowOf(l, 'CONFLICT', 'End date has passed but code ' + (fresh ? l.code : l.legacy) + ' exists. Tell XB.'));
      return;
    }
    const customer = data.customer || null;
    const found = customer && CUSTOMER_RE.test(String(customer.id)) ? customer : null;
    const foundEmail = found && found.defaultEmailAddress && typeof found.defaultEmailAddress.emailAddress === 'string'
      ? found.defaultEmailAddress.emailAddress.trim().toLowerCase() : '';
    if (!found) {
      decided.push(rowOf(l, 'NEEDS_SHOPIFY_ACCOUNT', 'No x-boundaries.com account with this email yet. Ask the traveller to '
        + 'sign up online with this email; checked again each morning.'));
      return;
    }
    if (foundEmail !== l.email) {
      decided.push(rowOf(l, 'CHECK_EMAIL', 'Shopify found an account but its email is not exactly this one. Check the email.'));
      return;
    }
    const customerNum = CUSTOMER_RE.exec(found.id)[1];
    if (fresh && old) {
      decided.push(rowOf(l, 'CONFLICT', 'Both ' + l.legacy + ' and ' + l.code + ' exist. Tell XB.', { customer: customerNum }));
      return;
    }
    const existing = fresh || old;
    if (existing) {
      const name = fresh ? l.code : l.legacy;
      const seen = inspect(existing, found.id, l);
      if (seen.conflict) {
        decided.push(rowOf(l, 'CONFLICT', 'Code ' + name + ' already exists and ' + seen.conflict + '. Nothing was changed. Tell XB.',
          { customer: customerNum }));
        return;
      }
      if (seen.atDefaults) {
        decided.push(rowOf(l, 'ADOPTED', 'Existing code kept (already 3 uses and this end date). Send it if the traveller '
          + 'does not have it yet.', { code: name, ends: l.end_label, ends_serial: l.end_serial, customer: customerNum,
          made: l.checked }));
        return;
      }
      writes.push({ row: l.row, kind: 'adopt', code: name, node_id: existing.id, customer: customerNum,
        end_iso: l.end_iso, end_label: l.end_label, end_serial: l.end_serial, checked: l.checked, key: l.key, query: ADOPT,
        variables: { id: existing.id, basicCodeDiscount: { usageLimit: USES, endsAt: l.end_iso, combinesWith: NONE } } });
      return;
    }
    writes.push({ row: l.row, kind: 'create', code: l.code, node_id: '', customer: customerNum,
      end_iso: l.end_iso, end_label: l.end_label, end_serial: l.end_serial, checked: l.checked, key: l.key, query: CREATE,
      variables: { basicCodeDiscount: { title: l.code, code: l.code, startsAt: new Date(Date.now()).toISOString(),
        endsAt: l.end_iso, customerGets: { value: { percentage: SHARE }, items: { all: true } },
        context: { customers: { add: [found.id] } }, usageLimit: USES, appliesOncePerCustomer: false,
        combinesWith: NONE, tags: ['X-Trekkers'] } } });
  });
  if (lookupFailed) problems.push({ code: 'lookup_failed', count: lookupFailed });
}

const all = (base.decided || []).concat(decided);
const plan = all.map((d) => ({ row: d.row, status: d.status, message: d.message, code: d.code }))
  .concat(writes.map((w) => ({ row: w.row, status: w.kind === 'create' ? 'would CREATE' : 'would ADOPT', code: w.code,
    ends: w.end_label })))
  .sort((a, b) => a.row - b.row);
const summary = { looked_up: lookups.length, writes: writes.length, creates: writes.filter((w) => w.kind === 'create').length,
  adopts: writes.filter((w) => w.kind === 'adopt').length, braked: writes.length > WRITE_CAP };
if (dryRun) return [{ json: { mode: 'dry_run', dry_run: true, writes: [], updates: [], plan, problems: [], summary } }];
if (writes.length > WRITE_CAP) {
  const held = writes.map((w) => ({ row: w.row, status: 'HELD', message: 'Too many codes at once; tried again next morning.',
    code: '', ends: '', customer: w.customer, checked: w.checked, made: '', key: w.key }));
  problems.push({ code: 'too_many_codes', count: writes.length });
  return [{ json: { mode: 'braked', dry_run: false, writes: [], updates: all.concat(held), plan: [], problems, summary } }];
}
return [{ json: { mode: writes.length ? 'write' : 'sheet_only', dry_run: false, writes, updates: all, plan: [], problems, summary } }];

// Check every code write of this run (#355). One result per write, in the same order as List Code
// Writes (Write Codes continues on its regular output, so a failed request is an item carrying
// `error`). A write counts as done only when Shopify answered with no errors and no userErrors, and
// the code it returns has 3 uses and the planned end date (and, for a new code, the planned name; for
// an adopted code, the same discount). Anything else is ERROR on the row, retried next run: the next
// run finds a code that was made after all and adopts it instead of making a second one.
const writes = $('List Code Writes').all().map((item) => item.json);
const results = $input.all().map((item) => item.json);
const base = $('Decide Code Writes').first().json;
const problems = (base.problems || []).slice();
const updates = (base.updates || []).slice();

const done = (write, result) => {
  if (!result || typeof result !== 'object' || result.error !== undefined) return false;
  if (Array.isArray(result.errors) && result.errors.length) return false;
  const answer = result.data && result.data[write.kind === 'create' ? 'discountCodeBasicCreate' : 'discountCodeBasicUpdate'];
  if (!answer || !Array.isArray(answer.userErrors) || answer.userErrors.length) return false;
  const node = answer.codeDiscountNode;
  const cd = node && node.codeDiscount;
  if (!node || typeof node.id !== 'string' || !cd || cd.__typename !== 'DiscountCodeBasic') return false;
  if (cd.usageLimit !== 3 || Date.parse(cd.endsAt) !== Date.parse(write.end_iso)) return false;
  if (write.kind === 'adopt') return node.id === write.node_id;
  const codes = cd.codes && Array.isArray(cd.codes.nodes) ? cd.codes.nodes : [];
  return codes.length === 1 && codes[0] && codes[0].code === write.code;
};

let failed = 0;
writes.forEach((write, i) => {
  const ok = results.length === writes.length && done(write, results[i]);
  if (!ok) {
    failed += 1;
    updates.push({ row: write.row, status: 'ERROR', message: 'Shopify did not confirm the code; tried again next morning.',
      code: '', ends: '', customer: write.customer, checked: write.checked, made: '', key: write.key });
    return;
  }
  updates.push(write.kind === 'create'
    ? { row: write.row, status: 'DONE', message: 'Code made. Send it to the traveller.', code: write.code,
      ends: write.end_label, ends_serial: write.end_serial, customer: write.customer, checked: write.checked,
      made: write.checked, key: write.key }
    : { row: write.row, status: 'ADOPTED', message: 'Existing code kept and set to 3 uses and this end date. Send it if the '
      + 'traveller does not have it yet.', code: write.code, ends: write.end_label, ends_serial: write.end_serial,
      customer: write.customer,
