  let invoiceRe;
  try { invoiceRe = new RegExp(String(raw.invoice_pattern)); } catch (e) { return null; }
  if (!/\((?!\?)/.test(String(raw.invoice_pattern))) return null; // must capture the invoice digits
  const cols = raw.columns;
  if (!cols || typeof cols !== 'object') return null;
  const names = {};
  for (const role of REQUIRED_ROLES.concat(OPTIONAL_ROLES)) {
    const name = cols[role] === null || cols[role] === undefined ? '' : cols[role];
    if (typeof name !== 'string' || name.length > 100) return null;
    if (!name.trim() && REQUIRED_ROLES.includes(role)) return null;
    names[role] = name.trim();
  }
  if (Object.keys(cols).some((role) => !(role in names))) return null;
  const used = Object.values(names).filter((n) => n);
  if (new Set(used).size !== used.length) return null; // two roles on one column
  return { tab: raw.tab, lastRow: raw.last_row, invoiceRe, names };
};
const locate = (layout, header) => {
  const cells = (header || []).map((h) => (h === undefined || h === null ? '' : String(h)).trim());
  const at = {};
  for (const [role, name] of Object.entries(layout.names)) {
    if (!name) { at[role] = -1; continue; }
    const hits = cells.reduce((list, h, i) => (h === name ? list.concat(i) : list), []);
    if (hits.length !== 1) return null;
    at[role] = hits[0];
