const WRITTEN = ['code', 'ends', 'status', 'message', 'customer', 'checked', 'made'];
const rolesFor = (u) => (u.status === 'DONE' || u.status === 'ADOPTED' ? WRITTEN
  : ['status', 'message', 'checked'].concat(u.customer ? ['customer'] : []));
const valueOf = (u, role) => (role === 'ends' ? (Number.isInteger(u.ends_serial) ? u.ends_serial : '')
  : (role === 'message' && (u.status === 'DONE' || u.status === 'ADOPTED') ? '' : String(u[role])));
const letter = (index) => {
  let n = index + 1;
  let out = '';
  while (n > 0) { const r = (n - 1) % 26; out = String.fromCharCode(65 + r) + out; n = Math.floor((n - 1) / 26); }
  return out;
};
const up = $('Rows To Update').first().json;
const again = $input.first().json || {};
const layout = layoutOf($('Run Settings').first().json.SHEET_LAYOUT);
const problems = (up.problems || []).slice();
const updates = up.updates || [];
const text = (value) => (value === undefined || value === null ? '' : String(value)).trim();
const data = [];
let moved = 0;
const at = layout && again.error === undefined && Array.isArray(again.values) ? locate(layout, again.values[0]) : null;
if (!at) {
  problems.push({ code: 'sheet_reread_failed', count: updates.length });
} else {
  const sheetName = "'" + layout.tab + "'";
  for (const u of updates) {
    const cells = again.values[u.row - 1] || [];
    const same = text(cells[at.invoice]) === u.key.invoice
      && (at.traveller < 0 ? '' : text(cells[at.traveller])) === u.key.traveller
      && text(cells[at.email]).toLowerCase() === u.key.email;
    if (!same) { moved += 1; continue; }
    for (const role of rolesFor(u)) {
      if (at[role] < 0) continue;
      data.push({ range: sheetName + '!' + letter(at[role]) + u.row, values: [[valueOf(u, role)]] });
