  summary: { planned: updates.length, writing: at ? rowsWritten : 0, cells: data.length, moved } } }];

// Check the write-back to the intake sheet (#355): Google must answer with one response per cell
// range sent. Anything else (an HTTP error after retries, a short answer) is one error alert; the
// next run writes the rows again.
const built = $('Build Sheet Update').first().json;
const answer = $input.first().json || {};
const problems = (built.problems || []).slice();
const ok = answer.error === undefined && Array.isArray(answer.responses) && answer.responses.length === built.expected;
// One response per cell range sent; the alert counts rows, not cells.
if (!ok) problems.push({ code: 'sheet_write_failed', count: built.summary.writing });
return [{ json: { mode: 'sheet_written', problems, summary: { ...built.summary, written: ok ? built.expected : 0 } } }];

// Turn this run's problems into one plain-English error alert for XB Ops Alert Email (system
// XT-CODES, #355). The only email this workflow ever causes: the daily health check counts these
// alerts the next morning. Row problems for the consultant (NEEDS_*, CHECK_*, CONFLICT) are never problems here;
// they stay in the sheet. Every line comes from the fixed templates below, keyed by closed codes, so
// no sheet text, name, email or Shopify text reaches the email.
const TEXT = {
  settings_invalid: () => 'the run settings are not valid, so nothing was checked or changed.',
  sheet_read_failed: () => 'the intake sheet could not be read, so nothing was checked or changed.',
  sheet_layout_changed: () => "the intake sheet's columns are not the agreed ones, so nothing was checked or changed.",
  token_failed: () => 'the sign-in to Shopify failed, so nothing was checked or changed.',
  too_many_rows: (n) => n + ' rows were waiting (more than 300), so none were checked today; they show HELD.',
  too_many_codes: (n) => n + ' codes would have been made or updated (more than 30), so none were; they show HELD.',
  lookup_failed: (n) => n + ' row(s) could not be checked in Shopify; they show ERROR and are tried again tomorrow.',
  write_failed: (n) => n + ' code(s) could not be made or updated; they show ERROR and are tried again tomorrow.',
  rows_moved: (n) => n + ' row(s) moved in the sheet during the run, so their result was not written; it is written tomorrow.',
  sheet_reread_failed: (n) => 'the sheet could not be read again before writing, so ' + n + ' row result(s) were not written; '
    + 'they are written tomorrow.',
  sheet_write_failed: (n) => n + ' row result(s) could not be written back to the sheet; they are written tomorrow.',
};
const CODE_RE = /^[a-z_]{1,40}$/;
const problems = ($input.first().json.problems || []).filter((p) => p && CODE_RE.test(p.code)
  && Object.prototype.hasOwnProperty.call(TEXT, p.code));
if (!problems.length) throw new Error('Build Error Alert reached without a known problem code');
const count = (p) => (Number.isInteger(p.count) && p.count >= 0 && p.count < 100000 ? p.count : 0);
const key = problems.length === 1 ? problems[0].code : 'several_problems';
return [{ json: { alert: { severity: 'ERROR', key, short: key,
  lines: ["XT trip discount codes: today's run had a problem. Ask Claude to check."]
    .concat(problems.slice(0, 10).map((p) => '- ' + TEXT[p.code](count(p))))
    .concat(['Detail for Claude: executions are not saved, so run it by hand with DRY_RUN on and read the plan.',
      ('Codes: ' + problems.map((p) => p.code + '=' + count(p)).join(', ')).slice(0, 300)]) } } }];
